// DecodeRecordInstallIntentRequest returns a decoder for requests sent to the
// platformMcp recordInstallIntent endpoint.
func DecodeRecordInstallIntentRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*platformmcp.RecordInstallIntentPayload, error) {
	return func(r *http.Request) (*platformmcp.RecordInstallIntentPayload, error) {
		var payload *platformmcp.RecordInstallIntentPayload
		var (
			body RecordInstallIntentRequestBody
			err  error
		)
		err = decoder(r).Decode(&body)
		if err != nil {
			if errors.Is(err, io.EOF) {
				return payload, goa.MissingPayloadError()
			}
			var gerr *goa.ServiceError
			if errors.As(err, &gerr) {
				return payload, gerr
			}
			return payload, goa.DecodePayloadError(err.Error())
		}
		err = ValidateRecordInstallIntentRequestBody(&body)
		if err != nil {
			return payload, err
		}

		var (
			sessionToken *string
		)
		sessionTokenRaw := r.Header.Get("Gram-Session")
		if sessionTokenRaw != "" {
			sessionToken = &sessionTokenRaw
		}
		payload = NewRecordInstallIntentPayload(&body, sessionToken)
		if payload.SessionToken != nil {
			if strings.Contains(*payload.SessionToken, " ") {
				// Remove authorization scheme prefix (e.g. "Bearer")
				cred := strings.SplitN(*payload.SessionToken, " ", 2)[1]
				payload.SessionToken = &cred
			}
		}

		return payload, nil
	}
}

